import{_ as o,l as r,o as e,c as n,v as t,p as s,x as l,d,i as m,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"音画同步","description":"","frontmatter":{"title":"音画同步","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/audio-visual-sync.md","filePath":"llm/audio-visual-sync.md","lastUpdated":1789023840000}'),c={name:"llm/audio-visual-sync.md"};function h(_,a,u,E,f,A){const i=r("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="音画同步" tabindex="-1">音画同步 <a class="header-anchor" href="#音画同步" aria-label="Permalink to &quot;音画同步&quot;">​</a></h1><div class="epigraph"><p>共享一个时钟比共享一套权重更硬。口型、节拍与物体碰撞必须落在同一时间戳上，否则 omni 只是并排播放。</p><footer>—— Chung, Zisserman, SyncNet；Prajwal 等 Wav2Lip；视频生成见 [时空建模](/llm/video-gen-spatiotemporal)</footer></div><p><a href="/llm/omni-model-alignment">上一课</a>把策略对齐写完。主干<a href="/llm/video-tokens">视频 token</a> 已要求时间 ID 对齐绝对时间。本课缺口是生成与理解里的音画锁相：说话口型、音乐节拍切镜、撞击声对上动作。本课程多模态生成到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>独立的文生视频 + TTS，只有全局文本相关，没有帧级互信息：嘴在动、声在响，相位却漂。SyncNet 用双塔判断口型与波形是否同步，成为说话脸的判别信号。Wav2Lip 等把唇形生成条件在音频特征上。视频扩散若只把 MEL 当全局向量，只能控风格不能控帧。需要把音频帧与视频帧写进同一时间网格（TM-RoPE 一类），或在损失里加同步判别。</p><p><span class="marginnote">同步是相对时延：50–100 ms 的口型错位人就能察觉。全局 CLIP 图文分完全看不见这件事。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>协议：音视频用同一时间戳采样（如 80 ms 一格）。训练：加 SyncNet 式对比/判别、或在 DiT 里交叉注意音频帧。评测：唇同步 LSE-C/D、节拍切镜对齐、人评「是否对上」，不要用 FID/FAD 单独过关。理解侧问答「第几秒出现鼓点」也依赖同一时钟，而不是只靠 <a href="/llm/clip">CLIP</a> 标签。</p>',8)),(e(),s(p,null,{default:l(()=>[m(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20AUD%5B%22%E9%9F%B3%E9%A2%91%E5%B8%A7%22%5D%20--%3E%20CLK%5B%22%E5%85%B1%E4%BA%AB%E6%97%B6%E9%97%B4%E6%A0%BC%22%5D%0A%20%20VID%5B%22%E8%A7%86%E9%A2%91%E5%B8%A7%22%5D%20--%3E%20CLK%0A%20%20CLK%20--%3E%20GEN%5B%22%E8%81%94%E5%90%88%E7%94%9F%E6%88%90%E6%88%96%E5%88%A4%E5%88%AB%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>锁相意味着条件从「这段音频的全局向量」变成「\\(t\\) 时刻的声学向量对 \\(t\\) 时刻的口型格」。注意力或卷积必须在时间维上局部；只有文本前缀时，模型会用语言先验补一段「像在说话」的嘴，相位随机。这与物体幻觉对称：没有帧级证据就用先验演。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>同步约束不解决内容安全，也不提高单帧分辨率。理解、生成、语音三条线在时钟上交汇；之后是系统与产品，不再展开新的主干课序。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>音画同步是共享时钟与帧级条件，不是并排播放。</li><li>口型与节拍要用同步损失或时间对齐的交叉注意。</li><li>全局嵌入看不见几十毫秒的错位。</li><li>出处：SyncNet；Wav2Lip；时空视频扩散与 omni 时间位置编码。</li></ul>',6))])}const S=o(c,[["render",h]]);export{B as __pageData,S as default};
